class Student:
    def __init__(self, name, m1, m2, m3):
        self.name = name
        self.marks = [m1, m2, m3]

    def average(self):
        return sum(self.marks) / len(self.marks)

s = Student("Rahul", 45, 72, 88)
print(s.name, "->", s.average())

