class Employee:
    def __init__(self, name, salary):
        self.name, self.salary = name, salary
    def show(self):
        print(self.name, self.salary)

class Manager(Employee):
    def __init__(self, name, salary, team):
        super().__init__(name, salary)
        self.team = team
    def show(self):
        super().show()
